import ast
import operator


def eval_expression(expr):
    """
    算術式を計算する。
    使用可能な演算子: +, -, *, /, //, %, **
    """

    binary_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }

    unary_operators = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError as e:
        raise ValueError("不正な式です") from e

    def calculate(node):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
                return node.value
            raise ValueError("数値以外は使用できません")

        if isinstance(node, ast.BinOp):
            left = calculate(node.left)
            right = calculate(node.right)

            if isinstance(node.op, (ast.Div, ast.FloorDiv, ast.Mod)) and right == 0:
                raise ZeroDivisionError("ゼロで割ることはできません")

            op = binary_operators.get(type(node.op))
            if op is None:
                raise ValueError("使用できない演算子です")

            return op(left, right)

        if isinstance(node, ast.UnaryOp):
            op = unary_operators.get(type(node.op))
            if op is None:
                raise ValueError("使用できない単項演算子です")
            return op(calculate(node.operand))

        raise ValueError("使用できない式です")

    return calculate(tree.body)
